package com.rodentcontrol.customer;
import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.concurrent.Executors;
public class MainActivity extends AppCompatActivity{
 TextView summary,msg;protected void onCreate(Bundle b){super.onCreate(b);if(SecureStore.token(this).isEmpty()){startActivity(new Intent(this,LoginActivity.class));finish();return;}setContentView(R.layout.activity_main);summary=findViewById(R.id.summary);msg=findViewById(R.id.message);findViewById(R.id.sites).setOnClickListener(v->startActivity(new Intent(this,SitesActivity.class)));findViewById(R.id.reports).setOnClickListener(v->startActivity(new Intent(this,ReportsActivity.class)));findViewById(R.id.incidents).setOnClickListener(v->startActivity(new Intent(this,IncidentsActivity.class)));findViewById(R.id.logout).setOnClickListener(v->logout());load();}
 void load(){Executors.newSingleThreadExecutor().execute(()->{try{org.json.JSONObject s=Api.dashboard(this).getJSONObject("stats");runOnUiThread(()->summary.setText("Địa điểm: "+s.optInt("sites")+"\nĐiểm kiểm soát: "+s.optInt("control_points")+"\nChuyến đã hoàn tất: "+s.optInt("completed_visits")+"\nSự cố chưa xử lý: "+s.optInt("open_incidents")+"\nBáo cáo đã duyệt: "+s.optInt("approved_reports")));}catch(Exception e){runOnUiThread(()->msg.setText(e.getMessage()));}});}
 void logout(){Executors.newSingleThreadExecutor().execute(()->{try{Api.logout(this);}catch(Exception ignored){}runOnUiThread(()->{startActivity(new Intent(this,LoginActivity.class));finish();});});}
}
